 void WillowPorch(Node3D n){Box(n,new(0,-.08f,7.7f),new(5,.2f,3.2f),new(.31f,.29f,.23f),true);for(int i=0;i<20;i++){var plank=Box(n,new(-2.38f+i*.25f,.035f,7.7f),new(.23f,.06f,3.15f),new(.37f,.34f,.27f));if(i==2||i==18)plank.RotationDegrees=new(i==2?3:-4,0,0);}for(int side=-1;side<=1;side+=2){float x=side*2.15f;Tube(n,new(x,0,8.7f),new(x,2.7f,8.7f),.065f,new(.49f,.46f,.39f));for(float h=.2f;h<2.7f;h+=.8f)Bevel(n,new(x,h,8.7f),new(.22f,.12f,.22f),new(.52f,.48f,.40f));Tube(n,new(x,2.25f,8.7f),new(x-side*.55f,2.8f,8.7f),.055f,new(.48f,.43f,.35f));for(int j=0;j<4;j++)Tube(n,new(x,2.4f+j*.09f,8.7f),new(x-side*(.15f+j*.12f),2.8f,8.7f),.016f,new(.48f,.43f,.35f));if(side<0){Tube(n,new(x,.95f,7),new(x,.95f,8.7f),.045f,new(.45f,.41f,.34f));for(int i=0;i<5;i++)Tube(n,new(x,.1f,7+i*.35f),new(x,.95f,7+i*.35f),.022f,new(.45f,.41f,.34f));}else for(int i=0;i<3;i++){var debris=Box(n,new(2.7f+i*.25f,.15f+i*.08f,9.1f),new(.15f,.10f,1.5f),Wood);debris.RotationDegrees=new(0,25+i*22,12);}}
  var canopy=Box(n,new(0,2.95f,7.7f),new(5.5f,.15f,3.2f),new(.27f,.26f,.21f));canopy.RotationDegrees=new(5,0,-2);canopy.MaterialOverride=WillowShingles();Box(n,new(0,2.75f,8.9f),new(5.2f,.2f,.18f),new(.48f,.44f,.36f));}
